<?php require 'config.php';
$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sort=$_GET['sort']??'new';
$sql="SELECT b.*,c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.status='active'";$args=[];
if($q!==''){$sql.=' AND (b.title LIKE ? OR b.code LIKE ? OR b.author LIKE ? OR b.publisher LIKE ?)';$like="%$q%";array_push($args,$like,$like,$like,$like);}if($cat){$sql.=' AND b.category_id=?';$args[]=$cat;}
$order=['new'=>'b.created_at DESC','title'=>'b.title ASC','price_asc'=>'b.price ASC','price_desc'=>'b.price DESC'];$countSql='SELECT COUNT(*) FROM books b WHERE b.status=\'active\'';$countArgs=[];if($q!==''){$countSql.=' AND (b.title LIKE ? OR b.code LIKE ? OR b.author LIKE ? OR b.publisher LIKE ?)';$like="%$q%";array_push($countArgs,$like,$like,$like,$like);}if($cat){$countSql.=' AND b.category_id=?';$countArgs[]=$cat;}$countSt=$pdo->prepare($countSql);$countSt->execute($countArgs);$matched=(int)$countSt->fetchColumn();$perPage=12;$page=max(1,(int)($_GET['page']??1));$pages=max(1,(int)ceil($matched/$perPage));$page=min($page,$pages);$sql.=' ORDER BY '.($order[$sort]??$order['new']).' LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage);$st=$pdo->prepare($sql);$st->execute($args);$books=$st->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$total=$pdo->query("SELECT COUNT(*) FROM books WHERE status='active'")->fetchColumn();
header_html('Kho giáo trình'); ?>
